<section class="page-heading"><div><p class="eyebrow">GARDEZ UNE TRACE DE VOS PROCHAINES ENVIES</p><h1>Liste de souhaits</h1><p class="subheading">Ajoutez des liens, une priorité ou un prix estimé; transférez un achat dans votre garde-robe.</p></div></section>
<div class="wishlist-grid"><?php foreach($items as $item): ?><article class="wishlist-card"><div class="wishlist-image"><?php if($item['photo_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['photo_path']) ?>" alt=""><?php else: ?><span>☆</span><?php endif; ?><i class="priority-<?= e($item['priority']) ?>"><?= e(['low'=>'Basse','normal'=>'Normale','high'=>'Haute'][$item['priority']]) ?></i></div><div class="wishlist-body"><small><?= e($item['label_name']??'CATÉGORIE À DÉFINIR') ?> · <?= e(['wanted'=>'À acheter','pending'=>'En attente','purchased'=>'Acheté','dismissed'=>'Abandonné'][$item['status']]) ?></small><h2><?= e($item['name']) ?></h2><p><?= e(implode(' · ',array_filter([$item['brand'],$item['seller']]))) ?></p><?php if($item['estimated_price']!==null): ?><b class="wishlist-price"><?= e(number_format((float)$item['estimated_price'],2,',',' ')) ?> <?= e($item['currency']) ?></b><?php endif; ?><?php if($item['url']): ?><a class="text-link" href="<?= e($item['url']) ?>" target="_blank" rel="noopener noreferrer">Ouvrir le lien ↗</a><?php endif; ?><?php if($item['notes']): ?><p><?= e($item['notes']) ?></p><?php endif; ?><div class="wishlist-actions"><form method="post" action="<?= e(url('wishlist-status')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><select name="status" aria-label="Statut"><?php foreach(['wanted'=>'À acheter','pending'=>'En attente','purchased'=>'Acheté','dismissed'=>'Abandonné'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $item['status']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="button secondary">Mettre à jour</button></form><?php if($item['status']!=='dismissed'): ?><form method="post" action="<?= e(url('wishlist-convert')) ?>" data-confirm="Créer une pièce dans votre garde-robe à partir de cet article ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="button primary">Ajouter à ma garde-robe</button></form><?php endif; ?><form method="post" action="<?= e(url('wishlist-delete')) ?>" data-confirm="Retirer cet article de la liste ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="text-button">Supprimer</button></form></div></div></article><?php endforeach; ?>
<article class="wishlist-card wishlist-new"><h2>Ajouter une envie</h2><form method="post" action="<?= e(url('wishlist-save')) ?>" enctype="multipart/form-data"><?= csrf_field() ?><label>Nom *<input name="name" required maxlength="160"></label><div class="form-row"><label>Catégorie<select name="label_id"><option value="">À définir</option><?php foreach($labels as $label): ?><option value="<?= e($label['id']) ?>"><?= e($label['name']) ?></option><?php endforeach; ?></select></label><label>Priorité<select name="priority"><option value="normal">Normale</option><option value="high">Haute</option><option value="low">Basse</option></select></label></div><div class="form-row"><label>Marque<input name="brand"></label><label>Boutique<input name="seller"></label></div><div class="form-row"><label>Prix estimé<input type="number" step="0.01" min="0" name="estimated_price"></label><label>Devise<select name="currency"><option>USD</option><option>CDF</option><option>EUR</option></select></label></div><label>Lien externe<input type="url" name="url" placeholder="https://…"></label><label>Photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>5 Mo maximum</small></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="button primary">Ajouter à la liste <span>→</span></button></form></article></div>
